app.get("/api/me",async(req,res)=>{
    try{
        if(!req.session.userId){
            return res.json({user:null});
        }

        const user=await pg.get(
            "SELECT * FROM users WHERE id=?",
            [req.session.userId]
        );

        res.json({
            user:user?pub(user):null
        });

    }catch(e){
        console.error("ERREUR /api/me SUPABASE :",e);
        res.status(500).json({
            error:"Impossible de charger le compte."
        });
    }
});
