app.get("/api/articles", async (req, res) => {
    try {
        const q = String(req.query.q || "").trim();
        const cat = String(req.query.category || "").trim();

        let sql = `
            SELECT
                a.*,
                u.name AS author
            FROM articles a
            JOIN users u ON u.id = a.author_id
            WHERE a.published = 1
        `;

        const params = [];

        if (q) {
            sql += `
                AND (
                    a.title ILIKE ?
                    OR a.content ILIKE ?
                )
            `;
            params.push("%" + q + "%", "%" + q + "%");
        }

        if (cat) {
            sql += ` AND a.category = ? `;
            params.push(cat);
        }

        sql += `
            ORDER BY a.breaking DESC, a.created_at DESC
        `;

        const articles = await pg.all(sql, params);

        res.json(articles);

    } catch (error) {
        console.error("GET /api/articles :", error);

        res.status(500).json({
            error: "Impossible de charger les articles."
        });
    }
});
app.get("/api/breaking", async (req, res) => {
    try {
        const articles = await pg.all(`
            SELECT
                a.id,
                a.title,
                a.excerpt,
                a.image,
                u.name AS author
            FROM articles a
            JOIN users u ON u.id = a.author_id
            WHERE a.published = 1
              AND a.breaking = 1
            ORDER BY a.created_at DESC
            LIMIT 6
        `);

        res.json(articles);

    } catch (error) {
        console.error("GET /api/breaking :", error);

        res.status(500).json({
            error: "Impossible de charger les actualitÃ©s urgentes."
        });
    }
});
app.get("/api/articles/:id", async (req, res) => {
    try {
        const article = await pg.get(`
            SELECT
                a.*,
                u.name AS author,
                u.avatar AS author_avatar
            FROM articles a
            JOIN users u ON u.id = a.author_id
            WHERE a.id = ?
        `, [req.params.id]);

        if (!article || !article.published) {
            return res.status(404).json({
                error: "Article introuvable."
            });
        }

        await pg.run(`
            UPDATE articles
            SET views = COALESCE(views, 0) + 1
            WHERE id = ?
        `, [article.id]);

        article.views = (article.views || 0) + 1;

        article.comments = await pg.all(`
            SELECT id, name, content, created_at
            FROM comments
            WHERE article_id = ?
              AND approved = 1
            ORDER BY created_at DESC
        `, [article.id]);

       article.reactions = db.prepare(`
    SELECT reaction, COUNT(*) AS count
    FROM reactions
    WHERE article_id = ?
    GROUP BY reaction
`).all(article.id);

        res.json(article);

    } catch (error) {
        console.error("GET /api/articles/:id :", error);

        res.status(500).json({
            error: "Impossible de charger l'article."
        });
    }
});
app.post("/api/articles/:id/comments", auth, async (req, res) => {
    try {
        const content = String(req.body.content || "")
            .trim()
            .slice(0, 1200);

        const user = await pg.get(
            "SELECT name FROM users WHERE id = ?",
            [req.session.userId]
        );

        if (!user) {
            return res.status(401).json({
                error: "Utilisateur introuvable."
            });
        }

        if (!content) {
            return res.status(400).json({
                error: "Commentaire vide."
            });
        }

        const comment = await pg.get(`
            INSERT INTO comments
            (article_id, name, content, approved)
            VALUES (?, ?, ?, 1)
            RETURNING id, name, content, created_at
        `, [
            req.params.id,
            user.name,
            content
        ]);

        res.json({
            ok: true,
            comment
        });

    } catch (error) {
        console.error("POST /api/articles/:id/comments :", error);

        res.status(500).json({
            error: "Impossible d'envoyer le commentaire."
        });
    }
});
