app.get("/api/jobs", async (req, res) => {
    try {
        const jobs = await pg.all(`
            SELECT *
            FROM jobs
            WHERE active = 1
            ORDER BY created_at DESC
        `);

        res.json(jobs);

    } catch (error) {
        console.error("GET /api/jobs :", error);

        res.status(500).json({
            error: "Impossible de charger les offres."
        });
    }
});


