app.put("/api/admin/jobs/:id", staff, async (req, res) => {
    try {
        const {
            title,
            company,
            type,
            description,
            contact,
            image,
            discord,
            active
        } = req.body;

        if (!title || !company || !type || !description) {
            return res.status(400).json({
                error: "Titre, entreprise, type et description requis."
            });
        }

        const result = await pg.run(`
            UPDATE jobs SET
                title = ?,
                company = ?,
                type = ?,
                description = ?,
                contact = ?,
                image = ?,
                discord = ?,
                active = ?
            WHERE id = ?
        `, [
            String(title).trim(),
            String(company).trim(),
            String(type).trim(),
            String(description).trim(),
            contact ? String(contact).trim() : "",
            image || null,
            discord ? String(discord).trim() : "",
            active === false ? 0 : 1,
            req.params.id
        ]);

        res.json({
            ok: result.changes > 0
        });

    } catch (error) {
        console.error("PUT /api/admin/jobs/:id :", error);

        res.status(500).json({
            error: "Impossible de modifier l'offre."
        });
    }
});


app.delete("/api/admin/jobs/:id", staff, async (req, res) => {
    try {
        const result = await pg.run(
            "DELETE FROM jobs WHERE id = ?",
            [req.params.id]
        );

        res.json({
            ok: result.changes > 0
        });

    } catch (error) {
        console.error("DELETE /api/admin/jobs/:id :", error);

        res.status(500).json({
            error: "Impossible de supprimer l'offre."
        });
    }
});

