app.get("/api/admin/citizen-posts", staff, async (req, res) => {
    try {
        const posts = await pg.all(`
            SELECT
                p.*,
                u.name AS user_name,
                u.email
            FROM citizen_posts p
            JOIN users u ON u.id = p.user_id
            ORDER BY
                CASE
                    WHEN p.status = 'pending' THEN 0
                    ELSE 1
                END,
                p.created_at DESC
        `);

        res.json(posts);
    } catch (error) {
        console.error("GET /api/admin/citizen-posts :", error);
        res.status(500).json({
            error: "Impossible de charger les demandes citoyennes."
        });
    }
});

