app.get("/api/gallery", async (req, res) => {
    try {
        const gallery = await pg.all(`
            SELECT
                g.*,
                u.name AS author
            FROM gallery g
            LEFT JOIN users u ON u.id = g.author_id
            ORDER BY g.created_at DESC
            LIMIT 60
        `);

        res.json(gallery);
    } catch (error) {
        console.error("GET /api/gallery :", error);
        res.status(500).json({
            error: "Impossible de charger la galerie."
        });
    }
});

