app.post("/api/articles", staff, async (req, res) => {
    try {
        let { title, content, excerpt, category, image, breaking } = req.body;

        title = String(title || "").trim();
        content = String(content || "").trim();

        if (!title || !content) {
            return res.status(400).json({
                error: "Titre et contenu requis."
            });
        }

        const article = await pg.get(`
            INSERT INTO articles
            (title, content, excerpt, category, image, author_id, breaking)
            VALUES (?, ?, ?, ?, ?, ?, ?)
            RETURNING id
        `, [
            title,
            content,
            String(excerpt || content.slice(0, 220)),
            String(category || "Actualités"),
            image || null,
            req.session.userId,
            breaking ? 1 : 0
        ]);

        const created = await pg.get(`
            SELECT
                a.*,
                u.name AS author,
                u.avatar AS author_avatar
            FROM articles a
            JOIN users u ON u.id = a.author_id
            WHERE a.id = ?
        `, [article.id]);

        const d = await notifyArticle(created);

        await pg.run(`
            UPDATE articles
            SET discord_sent = ?, discord_error = ?
            WHERE id = ?
        `, [
            d.ok ? 1 : 0,
            d.ok ? null : d.error,
            article.id
        ]);

        const finalArticle = await pg.get(`
            SELECT
                a.*,
                u.name AS author,
                u.avatar AS author_avatar
            FROM articles a
            JOIN users u ON u.id = a.author_id
            WHERE a.id = ?
        `, [article.id]);

        res.json({
            article: finalArticle,
            discord: d
        });

    } catch (error) {
        console.error("POST /api/articles :", error);

        res.status(500).json({
            error: "Impossible de créer l'article."
        });
    }
});


