app.put("/api/articles/:id", staff, async (req, res) => {
    try {
        const article = await pg.get(
            "SELECT * FROM articles WHERE id = ?",
            [req.params.id]
        );

        if (!article) {
            return res.status(404).json({
                error: "Article introuvable."
            });
        }

        if (
            req.session.role !== "admin" &&
            article.author_id !== req.session.userId
        ) {
            return res.status(403).json({
                error: "Accès refusé."
            });
        }

        let {
            title,
            content,
            excerpt,
            category,
            image,
            breaking,
            published
        } = req.body;

        title = String(title || "").trim();
        content = String(content || "").trim();

        if (!title || !content) {
            return res.status(400).json({
                error: "Titre et contenu requis."
            });
        }

        await pg.run(`
            UPDATE articles
            SET
                title = ?,
                content = ?,
                excerpt = ?,
                category = ?,
                image = ?,
                breaking = ?,
                published = ?,
                updated_at = CURRENT_TIMESTAMP
            WHERE id = ?
        `, [
            title,
            content,
            String(excerpt || content.slice(0, 220)),
            String(category || "Actualités"),
            image || null,
            breaking ? 1 : 0,
            published === false ? 0 : 1,
            req.params.id
        ]);

        const updated = await pg.get(`
            SELECT
                a.*,
                u.name AS author,
                u.avatar AS author_avatar
            FROM articles a
            JOIN users u ON u.id = a.author_id
            WHERE a.id = ?
        `, [req.params.id]);

        res.json({
            article: updated
        });

    } catch (error) {
        console.error("PUT /api/articles/:id :", error);

        res.status(500).json({
            error: "Impossible de modifier l'article."
        });
    }
});

